package com.example.shortener.service;
import com.example.shortener.config.ShortenerProperties; import com.example.shortener.storage.InMemoryLinkStore; import com.example.shortener.validation.UrlValidator; import org.junit.jupiter.api.*; import static org.junit.jupiter.api.Assertions.*;
class ShortenerServiceTest {private ShortenerService service;@BeforeEach void setup(){var p=new ShortenerProperties("http://localhost:8080",":memory:","key",true,7,302,null,true,false,60,1,true);service=new ShortenerService(new InMemoryLinkStore(),p,new UrlValidator(p));}@Test void createsAndResolvesAlias(){var r=service.create("https://example.com/a","demo",null,null,"owner",null);assertTrue(r.created());assertEquals("demo",service.resolve("demo",null,null).code());}@Test void idempotencyReplay(){var a=service.create("https://example.com",null,null,null,"o","i");var b=service.create("https://example.com",null,null,null,"o","i");assertFalse(b.created());assertEquals(a.link().code(),b.link().code());}}
